import{_ as r,o as d,c as s,a2 as a}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"案例拆解","description":"","frontmatter":{},"headers":[],"relativePath":"cases/index.md","filePath":"cases/index.md","lastUpdated":1785844806000}'),e={name:"cases/index.md"};function o(n,t,i,l,c,g){return d(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="案例拆解" tabindex="-1">案例拆解 <a class="header-anchor" href="#案例拆解" aria-label="Permalink to &quot;案例拆解&quot;">​</a></h1><p>案例的价值不在于&quot;看别人做得多好&quot;，而在于<strong>看清楚一条创意是怎么一步步变成成片的</strong>，然后把其中可复用的部分抽出来。</p><h2 id="本板块内容" tabindex="-1">本板块内容 <a class="header-anchor" href="#本板块内容" aria-label="Permalink to &quot;本板块内容&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文章</th><th>说明</th></tr></thead><tbody><tr><td><a href="/cases/template">拆解模板（先读这篇）</a></td><td>统一的拆解格式，理解格式才能读懂后面的案例</td></tr><tr><td><a href="/cases/case-01-beverage-tvc">案例 01 · 饮料品牌短 TVC</a></td><td>视频链路的完整走法</td></tr><tr><td><a href="/cases/case-02-ecommerce-visual">案例 02 · 电商主图批量生产</a></td><td>静态图批量生产的一致性控制</td></tr><tr><td><a href="/cases/case-03-fries-social">案例 03 · 快餐薯条社媒短视频</a></td><td>食品类的食欲感与首尾帧控制</td></tr><tr><td><a href="/cases/case-04-vf-fries-crisp">案例 04 · VF 工艺薯条脆</a></td><td>看不见的工艺怎么视觉化，以及合规边界</td></tr><tr><td><a href="/cases/case-04-fries-crisp-formats">案例 04 附 · 片型可行性分析</a></td><td>动手之前那一步：这个产品该拍什么类型的片子</td></tr><tr><td><a href="/cases/case-05-lays-ai-video">案例 05 · 乐事薯片 AI 短片</a></td><td><strong>逆向拆解</strong>：从一支公开成片倒推它的结构、优点和问题</td></tr><tr><td><a href="/cases/case-06-kalshi-veo">案例 06 · Kalshi NBA 决赛 AI 广告</a></td><td><strong>逆向拆解</strong>：真实的出片率长什么样——300 条素材换 15 条可用</td></tr><tr><td><a href="/cases/case-07-yuanqi-fenzhong">案例 07 · 元气森林 × 分众众小智</a></td><td><strong>逆向拆解</strong>：一条创意裂变成 N 个场景版本，以及效率数字该打几折</td></tr><tr><td><a href="/cases/case-08-mixue-kling">案例 08 · 蜜雪冰城 × 可灵雪王特效</a></td><td><strong>逆向拆解</strong>：产出物不是片子，是让用户自己做片子的工具</td></tr></tbody></table><p>八个案例覆盖八种不同的东西，不要只挑一篇看：</p><table tabindex="0"><thead><tr><th>案例</th><th>核心技术点</th><th>核心判断</th></tr></thead><tbody><tr><td>01 · 饮料 TVC</td><td>图生视频优于文生视频</td><td>把情绪变化编码进色彩</td></tr><tr><td>02 · 电商主图</td><td>批量生产的一致性控制</td><td>先做完美 1 张，再复制 N 次</td></tr><tr><td>03 · 薯条短视频</td><td>首尾帧控制形变动作</td><td>不是所有广告都需要 Big Idea</td></tr><tr><td>04 · VF 薯条脆</td><td>生成实拍不到的画面</td><td>展示做法，不展示好处</td></tr><tr><td>05 · 乐事薯片</td><td>从成片倒推制作判断</td><td>素材变便宜之后，片子会变长</td></tr><tr><td>06 · Kalshi 广告</td><td>从公开流程倒推生产模式</td><td>出片率只有 4%，管理废片才是瓶颈</td></tr><tr><td>07 · 元气森林</td><td>场景化多版本分发</td><td>适配型批量 ≠ 测试型批量</td></tr><tr><td>08 · 蜜雪冰城</td><td>用户照片里合成 IP 形象</td><td>交付物可以是工具，不是片子</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">05–08 和前四篇的读法不一样</p><p>案例 01–04 是<strong>正向</strong>的：从 brief 走到成片，有 Prompt、有链路、有工期。</p><p>案例 05–08 是<strong>逆向</strong>的：拆的不是自己的项目，而是第三方公开的作品，所有结论都靠倒推。</p><p>四篇逆向案例<strong>手上的信息不一样，因此拆的东西也不一样</strong>：</p><table tabindex="0"><thead><tr><th></th><th>手上有什么</th><th>拆什么</th></tr></thead><tbody><tr><td><strong>05 · 乐事</strong></td><td>一支能看的成片</td><td><strong>成片</strong>：分镜、节奏、哪里露馅</td></tr><tr><td><strong>06 · Kalshi</strong></td><td>创作者公开的完整流程</td><td><strong>生产模式</strong>：出片率、链路、编制</td></tr><tr><td><strong>07 · 元气森林</strong></td><td>只有结果数字</td><td><strong>打法</strong>：多版本策略、数字可信度</td></tr><tr><td><strong>08 · 蜜雪冰城</strong></td><td>活动形态与传播数据</td><td><strong>形态</strong>：交付物为什么不是片子</td></tr></tbody></table><p><strong>看得见成片就拆成片，只看得见流程就拆流程，只有数字就拆数字怎么读——别硬凑自己没有的信息。</strong></p><p>**逆向拆解是可以大量做的练习。**公开的 AI 广告作品到处都是，看得多了，「哪里露馅」的判断力会长得很快——而这个判断力，正是做正向项目时最省时间的东西。</p></div><div class="warning custom-block"><p class="custom-block-title">一条反直觉的观察：新鲜度和信息量是反着的</p><p>07 是这批里最新的（2026 年），但公开细节最少，只有结果数字。</p><p>06 时间更早（2025 年 6 月），创作者却把 prompt、流程、失败率全部公开了——<strong>至今仍是信息量最大的一篇。</strong></p><p><strong>追最新的案例，通常只能拿到新闻；能拆的东西，往往在稍旧但公开充分的案例里。</strong></p></div><div class="tip custom-block"><p class="custom-block-title">03 和 04 建议对照着读</p><p>同样是薯条，一个卖<strong>感官</strong>（热和脆），一个卖<strong>工艺</strong>（VF 真空低温油炸）。</p><p>卖点性质不同，整条链路都不同：03 不需要 Big Idea、不需要法务审校，把感官做足即可；04 有一整天花在技术核查与合规审校上，不产出任何画面。</p><p><strong>这两篇放在一起，比任何一篇单独看都有价值。</strong></p></div><div class="warning custom-block"><p class="custom-block-title">关于这些案例的性质，分两类</p><p><strong>案例 01–04 是教学用的演示案例</strong>，用来展示拆解格式怎么用、一条链路的各环节怎么衔接。<strong>它们不是真实客户项目的复盘。</strong></p><p><strong>案例 05–06 拆的是真实存在的第三方公开作品</strong>，但所有结论都是外部倒推，不是原作者提供的制作记录。数字均为公开口径，未经核实。</p><p>真正有价值的是你自己项目的记录。做完一个项目就用 <a href="/templates/case-study">案例拆解模板</a> 写一篇——那些才是别人抄不走的东西。</p></div><h2 id="怎么读案例" tabindex="-1">怎么读案例 <a class="header-anchor" href="#怎么读案例" aria-label="Permalink to &quot;怎么读案例&quot;">​</a></h2><p>不要顺着读一遍就完了。带着三个问题读：</p><ol><li><strong>它的 Big Idea 是什么？</strong> 用一句话复述。复述不出来，说明这个案例的创意本身就不清晰。</li><li><strong>哪一步是决定性的？</strong> 一条链路里通常有一两步决定了成败，其余是执行。找出那一步。</li><li><strong>哪部分能直接搬到我的项目？</strong> 通常不是创意（创意不能抄），而是<strong>流程和参数</strong>。</li></ol><h2 id="怎么写案例" tabindex="-1">怎么写案例 <a class="header-anchor" href="#怎么写案例" aria-label="Permalink to &quot;怎么写案例&quot;">​</a></h2><p>做完项目就写，别拖。三天后就想不起来当时为什么做那个决定了。</p><p>写的时候重点记两类东西：</p><ul><li><strong>失败的尝试</strong>。比成功的做法更有价值——它标记了边界在哪。</li><li><strong>决策的理由</strong>。「为什么选 A 不选 B」，这是下次能复用的判断，具体参数反而会过时。</li></ul><p>用 <a href="/templates/case-study">案例拆解模板</a>。</p>',18)])])}const b=r(e,[["render",o]]);export{h as __pageData,b as default};
